:root {
  --bg: #1a1a2e;
  --card-bg: #16213e;
  --primary: #e94560;
  --accent: #0f3460;
  --text: #eaeaea;
  --text-dim: #8899aa;
  --work-color: #e94560;
  --break-color: #2ecc71;
  --border: #0f3460;
  --shadow: #0a0a1a;
  --font: 'Courier New', Courier, monospace;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font);
  font-size: 16px;
  background: var(--bg);
  color: var(--text);
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
  background-image:
    linear-gradient(rgba(15, 52, 96, 0.15) 1px, transparent 1px),
    linear-gradient(90deg, rgba(15, 52, 96, 0.15) 1px, transparent 1px);
  background-size: 16px 16px;
}

.card {
  background: var(--card-bg);
  border: 4px solid var(--border);
  box-shadow:
    8px 8px 0 var(--shadow),
    inset 0 0 0 2px var(--bg);
  padding: 32px 24px;
  width: 100%;
  max-width: 420px;
  text-align: center;
  position: relative;
}

.header {
  margin-bottom: 24px;
}

.title {
  font-size: 20px;
  letter-spacing: 3px;
  color: var(--primary);
  text-shadow: 2px 2px 0 var(--shadow);
}

.mode-switcher {
  display: flex;
  gap: 8px;
  margin-bottom: 24px;
  justify-content: center;
}

.mode-btn {
  font-family: var(--font);
  font-size: 14px;
  font-weight: bold;
  letter-spacing: 1px;
  padding: 10px 16px;
  border: 3px solid var(--border);
  background: var(--bg);
  color: var(--text-dim);
  cursor: pointer;
  transition: none;
  box-shadow: 3px 3px 0 var(--shadow);
  min-height: 44px;
}

.mode-btn:hover {
  background: var(--accent);
  color: var(--text);
}

.mode-btn:focus-visible {
  outline: 3px solid var(--primary);
  outline-offset: 2px;
}

.mode-btn:active {
  transform: translate(2px, 2px);
  box-shadow: 1px 1px 0 var(--shadow);
}

.mode-btn.active {
  background: var(--accent);
  color: var(--text);
  border-color: var(--primary);
}

.timer-section {
  margin-bottom: 32px;
}

.timer-display {
  font-size: 72px;
  font-weight: bold;
  letter-spacing: 4px;
  color: var(--work-color);
  text-shadow: 4px 4px 0 var(--shadow);
  line-height: 1.1;
  transition: color 0.3s;
}

.timer-display.break-mode {
  color: var(--break-color);
}

.timer-display.finished {
  animation: blink 0.5s step-end infinite;
}

@keyframes blink {
  50% { opacity: 0.3; }
}

.status-label {
  font-size: 14px;
  letter-spacing: 2px;
  color: var(--text-dim);
  margin-top: 8px;
}

.controls {
  display: flex;
  gap: 12px;
  justify-content: center;
  margin-bottom: 24px;
}

.control-btn {
  font-family: var(--font);
  font-size: 16px;
  font-weight: bold;
  letter-spacing: 2px;
  padding: 14px 28px;
  border: 3px solid var(--border);
  background: var(--bg);
  color: var(--text);
  cursor: pointer;
  box-shadow: 4px 4px 0 var(--shadow);
  min-height: 48px;
  min-width: 100px;
}

.control-btn:hover {
  background: var(--accent);
}

.control-btn:focus-visible {
  outline: 3px solid var(--primary);
  outline-offset: 2px;
}

.control-btn:active {
  transform: translate(3px, 3px);
  box-shadow: 1px 1px 0 var(--shadow);
}

.control-btn.primary {
  background: var(--primary);
  color: #fff;
  border-color: var(--primary);
}

.control-btn.primary:hover {
  background: #c73550;
}

.footer {
  font-size: 12px;
  color: var(--text-dim);
  letter-spacing: 1px;
}

kbd {
  background: var(--bg);
  border: 2px solid var(--border);
  padding: 2px 6px;
  font-family: var(--font);
  font-size: 11px;
}

@media (max-width: 400px) {
  .card {
    padding: 24px 16px;
  }
  .timer-display {
    font-size: 56px;
  }
  .mode-btn {
    font-size: 12px;
    padding: 8px 12px;
  }
  .control-btn {
    font-size: 14px;
    padding: 12px 20px;
    min-width: 80px;
  }
  .title {
    font-size: 16px;
  }
}

(function () {
  'use strict';

  var WORK_SECONDS = 25 * 60;
  var BREAK_SECONDS = 5 * 60;

  var timerDisplay = document.getElementById('timer-display');
  var statusLabel = document.getElementById('status-label');
  var startPauseBtn = document.getElementById('start-pause');
  var resetBtn = document.getElementById('reset');
  var modeWorkBtn = document.getElementById('mode-work');
  var modeBreakBtn = document.getElementById('mode-break');

  var mode = 'work';
  var status = 'idle'; // idle | running | paused | finished
  var remaining = WORK_SECONDS;
  var endTime = 0;
  var tickHandle = null;

  function formatTime(seconds) {
    var m = Math.floor(seconds / 60);
    var s = seconds % 60;
    return (m < 10 ? '0' : '') + m + ':' + (s < 10 ? '0' : '') + s;
  }

  function render() {
    timerDisplay.textContent = formatTime(remaining);
    timerDisplay.classList.toggle('break-mode', mode === 'break');
    timerDisplay.classList.toggle('finished', status === 'finished');

    if (status === 'running') {
      statusLabel.textContent = 'RUNNING';
      startPauseBtn.textContent = 'PAUSE';
    } else if (status === 'paused') {
      statusLabel.textContent = 'PAUSED';
      startPauseBtn.textContent = 'START';
    } else if (status === 'finished') {
      statusLabel.textContent = 'TIME UP';
      startPauseBtn.textContent = 'START';
    } else {
      statusLabel.textContent = 'READY';
      startPauseBtn.textContent = 'START';
    }

    modeWorkBtn.classList.toggle('active', mode === 'work');
    modeBreakBtn.classList.toggle('active', mode === 'break');
    modeWorkBtn.setAttribute('aria-pressed', mode === 'work' ? 'true' : 'false');
    modeBreakBtn.setAttribute('aria-pressed', mode === 'break' ? 'true' : 'false');
  }

  function tick() {
    var now = Date.now();
    var diff = Math.max(0, Math.round((endTime - now) / 1000));
    if (diff !== remaining) {
      remaining = diff;
      render();
    }
    if (remaining <= 0) {
      stopTick();
      status = 'finished';
      render();
    }
  }

  function startTick() {
    stopTick();
    tickHandle = setInterval(tick, 250);
  }

  function stopTick() {
    if (tickHandle !== null) {
      clearInterval(tickHandle);
      tickHandle = null;
    }
  }

  function startTimer() {
    if (status === 'finished') {
      remaining = mode === 'work' ? WORK_SECONDS : BREAK_SECONDS;
    }
    endTime = Date.now() + remaining * 1000;
    status = 'running';
    startTick();
    render();
  }

  function pauseTimer() {
    stopTick();
    remaining = Math.max(0, Math.round((endTime - Date.now()) / 1000));
    status = 'paused';
    render();
  }

  function resetTimer() {
    stopTick();
    status = 'idle';
    remaining = mode === 'work' ? WORK_SECONDS : BREAK_SECONDS;
    render();
  }

  function setMode(newMode) {
    if (mode === newMode) return;
    mode = newMode;
    resetTimer();
  }

  startPauseBtn.addEventListener('click', function () {
    if (status === 'running') {
      pauseTimer();
    } else {
      startTimer();
    }
  });

  resetBtn.addEventListener('click', resetTimer);

  modeWorkBtn.addEventListener('click', function () { setMode('work'); });
  modeBreakBtn.addEventListener('click', function () { setMode('break'); });

  document.addEventListener('keydown', function (e) {
    if (e.target.tagName === 'BUTTON' && (e.key === ' ' || e.key === 'Enter')) {
      return;
    }
    if (e.key === ' ') {
      e.preventDefault();
      startPauseBtn.click();
    } else if (e.key === 'r' || e.key === 'R') {
      resetBtn.click();
    }
  });

  render();
})();
